using CTXD.Server.Data;using Npgsql;
namespace CTXD.Server.Services;
public sealed record IronTier(long Iron,int RewardIron);public sealed record IronActivityView(long ActivityId,long Iron,int RewardTimes,int Received,int NeedIron,long RemainingIron,DateTimeOffset EndsAt,IronTier[] Tiers);public sealed record IronClaimRequest(string RequestKey);public sealed record IronClaimResult(int Iron,int Received);
public sealed class IronActivityService(GameDb db,GamePushHub push,ISystemMailSender mail)
{
 public async Task FinalizeAsync(long activityId,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);string rules;await using(var q=new NpgsqlCommand("SELECT params_info FROM scheduled_activities WHERE id=$1 AND activity_type=5 AND status=2",c)){q.Parameters.AddWithValue(activityId);rules=Convert.ToString(await q.ExecuteScalarAsync(ct))??"";}if(string.IsNullOrEmpty(rules))return;var tiers=Parse(rules);var players=new List<long>();await using(var q=new NpgsqlCommand("SELECT player_id FROM player_iron_activity WHERE activity_id=$1 AND received_level<reward_level",c)){q.Parameters.AddWithValue(activityId);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))players.Add(r.GetInt64(0));}foreach(var player in players){await using var t=await c.BeginTransactionAsync(ct);int received,reward;await using(var q=new NpgsqlCommand("SELECT received_level,reward_level FROM player_iron_activity WHERE player_id=$1 AND activity_id=$2 FOR UPDATE",c,t)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(activityId);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct)){await t.RollbackAsync(ct);continue;}received=r.GetInt32(0);reward=r.GetInt32(1);}var amount=tiers.Skip(received).Take(reward-received).Sum(x=>x.RewardIron);if(amount>0){await using var save=new NpgsqlCommand("UPDATE player_iron_activity SET received_level=reward_level,updated_at=now() WHERE player_id=$1;UPDATE player_resources SET iron=iron+$2 WHERE player_id=$1",c,t);save.Parameters.AddWithValue(player);save.Parameters.AddWithValue(amount);await save.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);if(amount>0){await mail.SendAsync(player,"Iron rebate reward",$"Unclaimed iron rebate rewards were settled: {amount} iron.",[],$"iron-expiry-mail:{activityId}",ct);await push.SendAsync(player,"activity.updated",new{kind="iron",expired=true,amount},ct);}}}
 public async Task RecordGainAsync(NpgsqlConnection c,NpgsqlTransaction t,long player,long iron,CancellationToken ct){if(iron<=0)return;var a=await ActiveAsync(c,t,ct);if(a is null)return;var tiers=Parse(a.Value.rules);long before;await using(var q=new NpgsqlCommand("SELECT CASE WHEN activity_id=$2 THEN iron_gained ELSE 0 END FROM player_iron_activity WHERE player_id=$1 FOR UPDATE",c,t)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(a.Value.id);before=Convert.ToInt64(await q.ExecuteScalarAsync(ct)??0L);}var after=checked(before+iron);var reward=tiers.Count(x=>after>=x.Iron);await using var save=new NpgsqlCommand("INSERT INTO player_iron_activity(player_id,activity_id,iron_gained,reward_level) VALUES($1,$2,$3,$4) ON CONFLICT(player_id) DO UPDATE SET activity_id=$2,iron_gained=CASE WHEN player_iron_activity.activity_id=$2 THEN player_iron_activity.iron_gained+$3 ELSE $3 END,reward_level=$4,received_level=CASE WHEN player_iron_activity.activity_id=$2 THEN player_iron_activity.received_level ELSE 0 END,updated_at=now()",c,t);save.Parameters.AddWithValue(player);save.Parameters.AddWithValue(a.Value.id);save.Parameters.AddWithValue(iron);save.Parameters.AddWithValue(reward);await save.ExecuteNonQueryAsync(ct);}
 public async Task<IronActivityView> GetAsync(long player,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);var a=await ActiveAsync(c,null,ct)??throw new GameException("IRON_ACTIVITY_UNAVAILABLE","Iron activity is unavailable.");var tiers=Parse(a.rules);long iron=0;int reward=0,received=0;await using(var q=new NpgsqlCommand("SELECT iron_gained,reward_level,received_level FROM player_iron_activity WHERE player_id=$1 AND activity_id=$2",c)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(a.id);await using var r=await q.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){iron=r.GetInt64(0);reward=r.GetInt32(1);received=r.GetInt32(2);}}var next=tiers.FirstOrDefault(x=>iron<x.Iron);return new(a.id,iron,reward-received,received,next is null?0:checked((int)Math.Min(int.MaxValue,next.Iron-iron)),tiers.Skip(received).Sum(x=>(long)x.RewardIron),a.end,tiers);}
 public async Task<IronClaimResult> ClaimAsync(long player,string key,CancellationToken ct){if(string.IsNullOrWhiteSpace(key))throw new GameException("IRON_REQUEST_INVALID","Request key is required.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await using(var old=new NpgsqlCommand("SELECT reward_iron,reward_level FROM player_iron_claims WHERE player_id=$1 AND request_key=$2",c,t)){old.Parameters.AddWithValue(player);old.Parameters.AddWithValue(key);await using var r=await old.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){var result=new IronClaimResult(r.GetInt32(0),r.GetInt32(1));await t.CommitAsync(ct);return result;}}var a=await ActiveAsync(c,t,ct)??throw new GameException("IRON_ACTIVITY_UNAVAILABLE","Iron activity is unavailable.");var tiers=Parse(a.rules);int received,reward;await using(var q=new NpgsqlCommand("SELECT received_level,reward_level FROM player_iron_activity WHERE player_id=$1 AND activity_id=$2 FOR UPDATE",c,t)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(a.id);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("IRON_REWARD_EMPTY","No iron reward is available.");received=r.GetInt32(0);reward=r.GetInt32(1);}if(received>=reward)throw new GameException("IRON_REWARD_EMPTY","No iron reward is available.");var amount=tiers[received].RewardIron;await using(var save=new NpgsqlCommand("UPDATE player_iron_activity SET received_level=received_level+1,updated_at=now() WHERE player_id=$1;UPDATE player_resources SET iron=iron+$3 WHERE player_id=$1;INSERT INTO player_iron_claims(player_id,request_key,activity_id,reward_level,reward_iron) VALUES($1,$2,$4,$5,$3)",c,t)){save.Parameters.AddWithValue(player);save.Parameters.AddWithValue(key);save.Parameters.AddWithValue(amount);save.Parameters.AddWithValue(a.id);save.Parameters.AddWithValue(received+1);await save.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);await push.SendAsync(player,"activity.updated",new{kind="iron",amount},ct);return new(amount,received+1);}
 static IronTier[] Parse(string raw)=>raw.Split(';',StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split(',')).Select(x=>new IronTier(long.Parse(x[0]),int.Parse(x[1]))).ToArray();static async Task<(long id,DateTimeOffset end,string rules)?> ActiveAsync(NpgsqlConnection c,NpgsqlTransaction? t,CancellationToken ct){await using var q=new NpgsqlCommand("SELECT id,end_at,params_info FROM scheduled_activities WHERE activity_type=5 AND status=1 AND start_at<=now() AND end_at>now() ORDER BY start_at DESC LIMIT 1",c,t);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?(r.GetInt64(0),r.GetFieldValue<DateTimeOffset>(1),r.GetString(2)):null;}
}
